import React, { useEffect, useRef, useState } from 'react';
import mermaid from 'mermaid';
import './SvgFlow.css';

// Initialize mermaid with better defaults
mermaid.initialize({
  startOnLoad: true,
  theme: 'neutral',
  securityLevel: 'loose',
  flowchart: {
    curve: 'basis',
    padding: 15,
    nodeSpacing: 50,
    rankSpacing: 50,
    htmlLabels: true,
    useMaxWidth: true
  }
});

const SvgFlow = ({ code, language }) => {
  const mermaidRef = useRef(null);
  const [error, setError] = useState(null);
  const [isLoading, setIsLoading] = useState(false);

  const parseCodeToFlowchart = (code) => {
    try {
      if (!code.trim()) {
        throw new Error('No code provided');
      }

      let flowchartDef = 'graph TD\n';
      // Enhanced styling
      flowchartDef += '  classDef default fill:#f8f9fa,stroke:#495057,stroke-width:2px;\n';
      flowchartDef += '  classDef condition fill:#e7f5ff,stroke:#228be6,stroke-width:2px;\n';
      flowchartDef += '  classDef action fill:#f1f3f5,stroke:#495057,stroke-width:2px;\n';
      flowchartDef += '  classDef loop fill:#fff4e6,stroke:#f76707,stroke-width:2px;\n';

      // Parse different code patterns based on language
      switch (language?.toLowerCase()) {
        case 'javascript':
        case 'typescript':
          return parseJavaScriptCode(code, flowchartDef);
        case 'python':
          return parsePythonCode(code, flowchartDef);
        default:
          return parseGenericCode(code, flowchartDef);
      }
    } catch (err) {
      setError(`Failed to parse code: ${err.message}`);
      return null;
    }
  };

  const parseJavaScriptCode = (code, flowchartDef) => {
    // Function detection
    const functionMatch = code.match(/(?:function|const|let|var)\s+(\w+)\s*(?:\(|\=)/);
    if (!functionMatch) return basicFlowchart(code, flowchartDef);

    const funcName = functionMatch[1];
    flowchartDef += `  Start([Start]):::default --> Func[${funcName}]:::action\n`;

    // Detect loops
    const hasLoop = code.includes('for') || code.includes('while');
    if (hasLoop) {
      flowchartDef += `  Func --> Loop[Loop]:::loop\n`;
      flowchartDef += `  Loop --> LoopEnd{Continue?}:::condition\n`;
      flowchartDef += `  LoopEnd -->|Yes| Loop\n`;
      flowchartDef += `  LoopEnd -->|No| Next\n`;
    }

    // Detect if-else
    if (code.includes('if')) {
      const condition = code.match(/if\s*\((.*?)\)/)?.[1] || 'condition';
      flowchartDef += `  ${hasLoop ? 'Next' : 'Func'} --> Condition{${condition}}:::condition\n`;
      flowchartDef += `  Condition -->|Yes| TrueBlock[True branch]:::action\n`;
      flowchartDef += `  Condition -->|No| FalseBlock[False branch]:::action\n`;
      flowchartDef += `  TrueBlock --> End([End]):::default\n`;
      flowchartDef += `  FalseBlock --> End\n`;
    } else {
      flowchartDef += `  ${hasLoop ? 'Next' : 'Func'} --> End([End]):::default\n`;
    }

    return flowchartDef;
  };

  const parsePythonCode = (code, flowchartDef) => {
    // Basic flowchart for Python (expand as needed)
    flowchartDef += `  Start([Start]):::default --> PyScript[Python Script]:::action\n`;
    flowchartDef += `  PyScript --> End([End]):::default\n`;
    return flowchartDef;
  };

  const parseGenericCode = (code, flowchartDef) => {
    // Fallback for unsupported languages
    flowchartDef += `  Start([Start]):::default --> CodeBlock["Code Block: ${code.replace(/"/g, '&quot;')}"]:::action\n`;
    flowchartDef += `  CodeBlock --> End([End]):::default\n`;
    return flowchartDef;
  };

  const basicFlowchart = (code, flowchartDef) => {
    flowchartDef += `  Start([Start]):::default --> Code[Code: ${code}]:::action\n`;
    flowchartDef += `  Code --> End([End]):::default\n`;
    return flowchartDef;
  };

  useEffect(() => {
    if (code && mermaidRef.current) {
      setError(null);
      setIsLoading(true);
      const graphDefinition = parseCodeToFlowchart(code);
      if (graphDefinition) {
        try {
          // Add unique ID to prevent rendering conflicts
          const uniqueId = `mermaid-${Date.now()}`;
          mermaid.render(uniqueId, graphDefinition)
            .then(({ svg }) => {
              if (mermaidRef.current) {
                mermaidRef.current.innerHTML = svg;
              }
            })
            .catch(err => {
              console.error('Mermaid render error:', err);
              setError(`Failed to render flowchart: ${err.message}`);
            })
            .finally(() => {
              setIsLoading(false);
            });
        } catch (err) {
          console.error('Mermaid process error:', err);
          setError(`Failed to process flowchart: ${err.message}`);
          setIsLoading(false);
        }
      } else {
        setIsLoading(false);
      }
    }
  }, [code]);

  return (
    <div className="flowchart-container">
      {isLoading ? (
        <div className="empty-message">
          Generating flowchart...
        </div>
      ) : error ? (
        <div className="error-message">
          {error}
        </div>
      ) : code ? (
        <div ref={mermaidRef} className="flowchart-content" />
      ) : (
        <div className="empty-message">
          No flowchart yet — click "Generate Flowchart"
        </div>
      )}
    </div>
  );
};

export default SvgFlow;
